// The stamp every file `x client` writes opens with: the command that regenerates it, the source
// document and its hash, and the hash of the file's own body. The `drift` step reads it back — a
// source that moved is `X_CLIENT_STALE`, a body that moved is `X_CLIENT_EDITED`.

import { t } from '@ultimat3/schema';

export const STAMP_MARKER = '// @x-client ';

/** What a generated file says about itself. */
export interface ClientStamp {
  /** The invocation that writes this file again, flags included. */
  readonly command: string;
  /** App-root-relative path of the document it was compiled from. */
  readonly source: string;
  readonly sourceHash: string;
  readonly bodyHash: string;
}

const stampSchema = t.object({
  command: t.string,
  source: t.string,
  sourceHash: t.string,
  bodyHash: t.string,
});

export const sha256 = (text: string): string =>
  new Bun.CryptoHasher('sha256').update(text).digest('hex');

const HEAD = (source: string): readonly string[] => [
  '// biome-ignore-all format: generated by x client; its bytes are hashed in the stamp below',
  `// GENERATED from ${source} by x client: never edit it, wrap it in a file of your own.`,
];

/** `body` with its header: the stamp names the hash of exactly the bytes after it. */
export function stamped(stamp: Omit<ClientStamp, 'bodyHash'>, body: string): string {
  const full: ClientStamp = { ...stamp, bodyHash: sha256(body) };
  const ordered = {
    command: full.command,
    source: full.source,
    sourceHash: full.sourceHash,
    bodyHash: full.bodyHash,
  };
  return `${[...HEAD(stamp.source), `${STAMP_MARKER}${JSON.stringify(ordered)}`].join('\n')}\n${body}`;
}

/** The stamp and the body after it; `undefined` for a file `x client` did not write. */
export function readStamp(
  text: string,
): { readonly stamp: ClientStamp; readonly body: string } | undefined {
  const at = text.indexOf(STAMP_MARKER);
  if (at < 0 || at > 400) return undefined;
  const end = text.indexOf('\n', at);
  if (end < 0) return undefined;
  let raw: unknown;
  try {
    raw = JSON.parse(text.slice(at + STAMP_MARKER.length, end));
  } catch {
    // A marker whose JSON does not parse is a hand edit of the stamp itself: the body hash below
    // cannot be read, so the file is reported as edited by the caller rather than skipped.
    return { stamp: { command: '', source: '', sourceHash: '', bodyHash: '' }, body: '' };
  }
  const parsed = stampSchema.safeParse(raw);
  if (!('value' in parsed)) {
    return { stamp: { command: '', source: '', sourceHash: '', bodyHash: '' }, body: '' };
  }
  return { stamp: parsed.value as ClientStamp, body: text.slice(end + 1) };
}
